<template><AdminLayout><Head title="Editorial"/><section class="p-6"><h1 class="text-2xl font-bold">Caderno editorial</h1><p class="my-3">Rascunhos e conteúdos de IA exigem revisão humana antes de publicar.</p><nav class="flex gap-5 my-5"><a href="/admin/editorial/posts/create">Nova publicação</a><a href="/admin/editorial/comments">Moderar comentários</a><a href="/blog">Ver blog KazaKora</a><a href="https://ferrakora.com/blog/" target="_blank" rel="noopener">Ver blog FerraKora</a></nav><p v-if="!posts.length">Nenhuma publicação cadastrada.</p><article v-for="post in posts" :key="post.id" class="border rounded p-4 my-3"><h2 class="font-bold"><a :href="`/admin/editorial/posts/${post.id}/edit`">{{post.title}}</a></h2><p><span class="rounded px-2 py-0.5 text-xs font-bold" :class="post.site==='ferrakora'?'bg-orange-100 text-orange-800':'bg-gray-100 text-gray-800'">{{post.site==='ferrakora'?'FerraKora':'KazaKora'}}</span> {{post.type}} · {{post.status}}</p><div class="flex gap-4 mt-3"><a :href="`/admin/editorial/posts/${post.id}/preview`">Prévia privada</a><button v-if="post.status==='published'" :disabled="action.processing" @click="action.post(`/admin/editorial/posts/${post.id}/unpublish`)">Despublicar</button></div></article><p v-for="(error,key) in action.errors" :key="key" role="alert">{{error}}</p></section></AdminLayout></template>
